from decorators import timer, logger, retry, cache, validate_types
import random


@timer
@validate_types(base_fee=int, discount=int)
def calculate_fee(base_fee, discount=0, gst=18):
    """Calculate course fee with discount and GST."""
    discounted = base_fee * (1 - discount / 100)
    return round(discounted * (1 + gst / 100), 2)


@retry(max_attempts=3, delay=0.5)
@logger
def fetch_student_data(student_id):
    """Simulate an unreliable API call."""
    if random.random() < 0.5:
        raise ConnectionError("Server timeout")
    return {"id": student_id, "name": "Rahul", "status": "active"}


@cache
@timer
def fibonacci(n):
    """Compute nth Fibonacci number with caching."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)


def demo():
    print("=" * 50)
    print("1. Fee Calculator (timer + validate_types)")
    print("=" * 50)
    print(f"Fee: ₹{calculate_fee(25000, discount=10):,}")

    try:
        calculate_fee("invalid", discount=10)  # Should raise TypeError
    except TypeError as e:
        print(f"Validation error: {e}")

    print(f"\n{'=' * 50}")
    print("2. Fibonacci (cache + timer)")
    print("=" * 50)
    print(f"fib(30) = {fibonacci(30)}")
    print(f"Cache: {fibonacci.cache_info()['size']} entries")

    print(f"\n{'=' * 50}")
    print("3. API Call (retry + logger)")
    print("=" * 50)
    try:
        result = fetch_student_data("TP-001")
        print(f"Success: {result}")
    except ConnectionError:
        print("All retries failed!")


if __name__ == "__main__":
    demo()
```

