import pytest
import time
from decorators import timer, logger, retry, cache, validate_types


# ── Fixtures ──────────────────────────────

@pytest.fixture
def cached_adder():
    """Provide a fresh cached function for each test."""
    @cache
    def add(a, b):
        return a + b
    return add


@pytest.fixture
def sample_fees():
    return [15000, 20000, 25000, 30000]


# ── Timer Tests ────────────────────────────

def test_timer_returns_correct_result():
    @timer
    def add(a, b):
        return a + b
    assert add(2, 3) == 5


def test_timer_preserves_function_name():
    @timer
    def my_function():
        pass
    assert my_function.__name__ == "my_function"


# ── Cache Tests ────────────────────────────

def test_cache_returns_correct_result(cached_adder):
    assert cached_adder(2, 3) == 5
    assert cached_adder(10, 20) == 30


def test_cache_stores_results(cached_adder):
    cached_adder(1, 2)
    cached_adder(3, 4)
    assert cached_adder.cache_info()["size"] == 2


def test_cache_clear(cached_adder):
    cached_adder(1, 2)
    cached_adder.cache_clear()
    assert cached_adder.cache_info()["size"] == 0


# ── Validate Types Tests ───────────────────

def test_validate_types_passes_valid():
    @validate_types(name=str, age=int)
    def register(name, age):
        return f"{name} is {age}"
    assert register("Rahul", 22) == "Rahul is 22"


def test_validate_types_rejects_invalid():
    @validate_types(name=str, age=int)
    def register(name, age):
        return f"{name} is {age}"
    with pytest.raises(TypeError):
        register("Rahul", "twenty")  # age should be int


# ── Retry Tests ────────────────────────────

def test_retry_succeeds_on_first_try():
    call_count = 0
    @retry(max_attempts=3, delay=0)
    def always_works():
        nonlocal call_count
        call_count += 1
        return "success"
    assert always_works() == "success"
    assert call_count == 1


def test_retry_succeeds_after_failures():
    attempt = 0
    @retry(max_attempts=3, delay=0)
    def fails_twice():
        nonlocal attempt
        attempt += 1
        if attempt < 3:
            raise ValueError("Not yet")
        return "done"
    assert fails_twice() == "done"


def test_retry_raises_after_max_attempts():
    @retry(max_attempts=2, delay=0)
    def always_fails():
        raise ConnectionError("Down")
    with pytest.raises(ConnectionError):
        always_fails()


# ── Parametrized Tests ─────────────────────

@pytest.mark.parametrize("base,discount,expected", [
    (10000, 0, 11800.0),
    (10000, 10, 10620.0),
    (10000, 50, 5900.0),
    (0, 10, 0.0),
])
def test_fee_calculation(base, discount, expected):
    @validate_types(base_fee=int, discount=int)
    def calc_fee(base_fee, discount=0, gst=18):
        discounted = base_fee * (1 - discount / 100)
        return round(discounted * (1 + gst / 100), 2)
    assert calc_fee(base, discount=discount) == expected
